// ─── Parse Evolution API webhook payload ───────────────────────────────────
const body = $input.first().json.body || $input.first().json;

const event = body.event || '';
const instance = body.instance || '';
const data = body.data || {};

// Only process MESSAGES_UPSERT events with actual content
if (event !== 'messages.upsert') {
  return [{ json: { skip: true, reason: 'not_messages_upsert', event } }];
}

const message = data.message || {};
const key = data.key || {};

// Ignore our own outgoing messages
if (key.fromMe === true) {
  return [{ json: { skip: true, reason: 'own_message' } }];
}

const remoteJid = key.remoteJid || '';
const phoneNumber = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');
const isGroup = remoteJid.includes('@g.us');

// Skip group messages (can be enabled later)
if (isGroup) {
  return [{ json: { skip: true, reason: 'group_message' } }];
}

// Detect message type
let messageType = 'unknown';
let textContent = '';
let locationLat = null;
let locationLng = null;

if (message.conversation || message.extendedTextMessage) {
  messageType = 'text';
  textContent = message.conversation || message.extendedTextMessage?.text || '';
} else if (message.locationMessage) {
  messageType = 'location';
  locationLat = message.locationMessage.degreesLatitude;
  locationLng = message.locationMessage.degreesLongitude;
} else if (message.liveLocationMessage) {
  messageType = 'location';
  locationLat = message.liveLocationMessage.degreesLatitude;
  locationLng = message.liveLocationMessage.degreesLongitude;
}

return [{
  json: {
    skip: false,
    messageType,
    phoneNumber,
    remoteJid,
    instance,
    textContent,
    locationLat,
    locationLng,
    rawMessage: message,
  }
}];

// ─── Get or init session from Redis-like state stored in n8n static data ────
// We use n8n's built-in workflow static data as a lightweight session store.
// For production, replace with Redis HTTP calls or Appwrite document reads.

const phoneNumber = $json.phoneNumber;
const lat = $json.locationLat;
const lng = $json.locationLng;

// Retrieve existing session
const workflowStaticData = $getWorkflowStaticData('global');
const sessions = workflowStaticData.sessions || {};
const session = sessions[phoneNumber] || { state: 'idle', lat: null, lng: null };

// User sent a location: save it and ask what they're looking for
session.lat = lat;
session.lng = lng;
session.state = 'awaiting_place_type';
session.updatedAt = new Date().toISOString();

workflowStaticData.sessions = { ...sessions, [phoneNumber]: session };

const replyText =
  'مرحباً بك! 👋\n\n' +
  'استلمت موقعك بنجاح. 📍\n\n' +
  'ماذا تبحث عنه؟ يمكنك اختيار:\n' +
  '🍽️ مطعم\n' +
  '☕ كافيه\n' +
  '💊 صيدلية\n' +
  '🏥 مستشفى\n' +
  '🛒 سوبرماركت\n' +
  '🕌 مسجد\n' +
  '⛽ محطة بنزين\n' +
  '🏧 صراف آلي\n\n' +
  'أو اكتب ما تريد البحث عنه بحرية!';

return [{
  json: {
    phoneNumber,
    remoteJid: $json.remoteJid,
    instance: $json.instance,
    replyText,
    sessionState: session.state,
    lat,
    lng,
  }
}];

// ─── Handle text message: check session state ────────────────────────────────
const phoneNumber = $json.phoneNumber;
const text = ($json.textContent || '').trim();

const workflowStaticData = $getWorkflowStaticData('global');
const sessions = workflowStaticData.sessions || {};
const session = sessions[phoneNumber] || { state: 'idle' };

let action = 'unknown';
let lat = session.lat || null;
let lng = session.lng || null;

if (session.state === 'awaiting_place_type' && lat && lng) {
  action = 'search_intent';   // user has location, now telling us what to find
} else if (session.state === 'idle' || !lat || !lng) {
  action = 'ask_location';    // no location yet
} else {
  action = 'search_intent';
}

return [{
  json: {
    phoneNumber,
    remoteJid: $json.remoteJid,
    instance: $json.instance,
    text,
    action,
    lat,
    lng,
    sessionState: session.state,
  }
}];

// ─── Merge intent response with session lat/lng ──────────────────────────────
const intentData = $json;   // output from LangChain intent node
const phoneNumber = intentData.phone_number ||
  $('Handle Text – Check Session').first().json.phoneNumber;
const lat = $('Handle Text – Check Session').first().json.lat;
const lng = $('Handle Text – Check Session').first().json.lng;
const remoteJid = $('Handle Text – Check Session').first().json.remoteJid;
const instance = $('Handle Text – Check Session').first().json.instance;

return [{
  json: {
    phoneNumber,
    remoteJid,
    instance,
    lat,
    lng,
    action: $('Handle Text – Check Session').first().json.action,
    place_type: intentData.place_type,
    confidence: intentData.confidence,
    suggested_reply: intentData.suggested_reply,
  }
}];

// ─── Format search results for WhatsApp via Evolution API ───────────────────
const searchResult = $json;

// Retrieve upstream context depending on which path we came from
let remoteJid, instance, phoneNumber;
try {
  remoteJid = $('Merge Intent + Session').first().json.remoteJid;
  instance  = $('Merge Intent + Session').first().json.instance;
  phoneNumber = $('Merge Intent + Session').first().json.phoneNumber;
} catch (_) {
  remoteJid = $('Handle Location – Save & Ask').first().json.remoteJid;
  instance  = $('Handle Location – Save & Ask').first().json.instance;
  phoneNumber = $('Handle Location – Save & Ask').first().json.phoneNumber;
}

const message = searchResult.formatted_message ||
  'عذراً، حدث خطأ أثناء البحث. يرجى المحاولة لاحقاً.';

return [{
  json: {
    remoteJid,
    instance,
    phoneNumber,
    message,
    totalFound: searchResult.total_found || 0,
  }
}];

// ─── No location yet: ask user to share location ─────────────────────────────
const phoneNumber = $json.phoneNumber ||
  $('Handle Text – Check Session').first().json.phoneNumber;
const remoteJid = $json.remoteJid ||
  $('Handle Text – Check Session').first().json.remoteJid;
const instance = $json.instance ||
  $('Handle Text – Check Session').first().json.instance;

const replyText =
  'مرحباً! 👋\n\n' +
  'لأتمكن من مساعدتك في البحث عن أماكن قريبة منك،\n' +
  'أرسل لي موقعك الجغرافي أولاً. 📍\n\n' +
  'في واتساب: اضغط على مشاركة الموقع ← الموقع الحالي';

return [{
  json: { phoneNumber, remoteJid, instance, replyText }
}];

// ─── Build suggested-reply (intent known but no location) ────────────────────
const intentData = $json;
const ctx = $('Handle Text – Check Session').first().json;

return [{
  json: {
    phoneNumber: ctx.phoneNumber,
    remoteJid: ctx.remoteJid,
    instance: ctx.instance,
    replyText: intentData.suggested_reply ||
      'أرسل لي موقعك الجغرافي وسأبحث لك فوراً! 📍',
  }
}];
